// Get raw content from the previous OpenAI node
let raw = $json.message.content || "";

// Remove code block wrappers if present
raw = raw.replace(/```json/g, "");
raw = raw.replace(/```/g, "");

// Replace em dash and en dash with comma
raw = raw.replace(/[—–]/g, ",");

// Trim whitespace
raw = raw.trim();

// Parse JSON safely
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error("Email JSON parsing failed. Raw content: " + raw);
}

// Fallback subject for Email 2 if missing
const email2SubjectFallback = "Just following up";

// Build clean output
return [
  {
    json: {
      email_1_subject: parsed.email_1?.subject || "",
      email_1_body: parsed.email_1?.body || "",

      email_2_subject: parsed.email_2?.subject || email2SubjectFallback,
      email_2_body: parsed.email_2?.body || "",

      email_3_subject: parsed.email_3?.subject || "",
      email_3_body: parsed.email_3?.body || ""
    }
  }
];

const messages = $json.messages;

// Always pick the SENT message as the anchor
const sentMessage = messages.find(
  m => m.labelIds && m.labelIds.includes("SENT")
);

if (!sentMessage) {
  throw new Error("No SENT message found in thread");
}

const headers = sentMessage.payload.headers;

const messageIdHeader = headers.find(
  h => h.name.toLowerCase() === "message-id"
);

const toHeader = headers.find(
  h => h.name.toLowerCase() === "to"
);

return {
  json: {
    Email: toHeader.value,
    Name: $input.item.json.Name,
    threadId: $json.id,
    messageId: messageIdHeader.value.replace(/[<>]/g, "")
  }
};

const input = $input.item.json;

// Get name from Loop1 node
const loopItems = $items("Loop1", 0);
const loopItem = loopItems.length > 0 ? loopItems[0].json : {};
const firstName = loopItem["First Name"] || loopItem.Name || "there";

const subject = "Re: The call you missed yesterday...";
const from = "Vamsi <vamsi@lumoscale.com>";
const to = input.Email;
const threadId = input.threadId;
const messageId = input.messageId;

const htmlBody = `
<p>Hello ${firstName},</p>

<p>Following up because this matters.</p>

<p>Most agents lose 3 to 5 deals per month to missed calls. That is $50K plus gone.</p>

<p>Our system guarantees:</p>

<ul>
  <li>Every call answered, in your voice</li>
  <li>Leads qualified automatically</li>
  <li>Showings booked instantly</li>
  <li>Follow ups and reminders handled</li>
</ul>

<p>Worth 15 minutes to talk?</p>

<p>Best,<br>
Vamsi, CEO<br>
Lumoscale</p>
`;

const emailContent =
`Subject: ${subject}
From: ${from}
To: ${to}
In-Reply-To: <${messageId}>
References: <${messageId}>
Content-Type: text/html; charset="UTF-8"

${htmlBody}`;

const raw = Buffer.from(emailContent)
  .toString("base64")
  .replace(/\+/g, "-")
  .replace(/\//g, "_")
  .replace(/=+$/, "");

return {
  json: {
    raw,
    threadId
  }
};

